<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> children</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
